import numpy as np

def solve_ladder(k):
    T = np.array([[1, 1, 1], [1, 0, 1], [1, 1, 0]], dtype=object)
    def mat_pow(A, p):
        res = np.eye(len(A), dtype=object)
        while p > 0:
            if p % 2 == 1:
                res = np.dot(res, A)
            A = np.dot(A, A)
            p //= 2
        return res

    if k == 1:
        return 3

    T_pow = mat_pow(T, k-1)
    v1 = np.array([1, 1, 1], dtype=object)
    vk = np.dot(T_pow, v1)
    return np.sum(vk)

print(solve_ladder(1))
print(solve_ladder(2))
print(solve_ladder(21))
